 import React, { useState, useEffect, useRef } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import VerifiedBadge from '../components/VerifiedBadge'
import { initiateCommunityPayment } from '../services/paymentService'
import { uploadImage } from '../services/uploadService' // ✅ Imported image uploader
import { 
  Loader, 
  Users, 
  FileText, 
  DollarSign, 
  CheckCircle, 
  Crown, 
  Lock,
  Building2,
  X,
  Heart,
  Image as ImageIcon // ✅ Imported image icon
} from 'lucide-react'

export default function CommunityDetail() {
    const { id } = useParams()
    const { user, profile } = useAuth()
    const { showToast } = useToast()
    const navigate = useNavigate()
    const [community, setCommunity] = useState(null)
    const [posts, setPosts] = useState([])
    const [isMember, setIsMember] = useState(false)
    const [isCreator, setIsCreator] = useState(false)
    const [loading, setLoading] = useState(true)
    const [showPaymentModal, setShowPaymentModal] = useState(false)
    
    // Post state
    const [newPost, setNewPost] = useState('')
    const [selectedImage, setSelectedImage] = useState(null)
    const [imagePreview, setImagePreview] = useState(null)
    const [submitting, setSubmitting] = useState(false)
    
    // Prediction modal state
    const [showPredictionModal, setShowPredictionModal] = useState(false)
    const [predictionData, setPredictionData] = useState({
        result: 'Draw',
        yellowCards: 2,
        redCards: 0,
        corners: 5,
        offsides: 1
    })

    const fileInputRef = useRef(null)

    useEffect(() => {
        loadCommunityData()
    }, [id, user])

    const loadCommunityData = async () => {
        setLoading(true)
        try {
            const { data: communityData } = await supabase
                .from('communities')
                .select('*, profiles:creator_id (id, username, full_name, avatar_url, is_verified)')
                .eq('id', id)
                .single()

            setCommunity(communityData)
            setIsCreator(user?.id === communityData?.creator_id)

            if (user) {
                const { data: memberData } = await supabase
                    .from('community_members')
                    .select('*')
                    .eq('community_id', id)
                    .eq('user_id', user.id)
                    .eq('status', 'active')
                    .maybeSingle()
                setIsMember(!!memberData)
            }

            const { data: postsData } = await supabase
                .from('community_posts')
                .select('*, profiles:user_id (id, username, full_name, avatar_url, is_verified)')
                .eq('community_id', id)
                .order('created_at', { ascending: false })

            setPosts(postsData || [])

            const { count } = await supabase
                .from('community_members')
                .select('*', { count: 'exact', head: true })
                .eq('community_id', id)
                .eq('status', 'active')

            if (communityData) {
                setCommunity({ ...communityData, member_count: count || 0 })
            }

        } catch (error) {
            console.error('Error loading community:', error)
            showToast('Failed to load community data', 'error')
        } finally {
            setLoading(false)
        }
    }

    const handleJoin = () => {
        if (!user) {
            showToast('Please sign in to join this community', 'warning')
            navigate('/login')
            return
        }
        setShowPaymentModal(true)
    }

    const handlePayment = async () => {
        if (!user) {
            showToast('Please sign in first', 'error')
            return
        }

        setSubmitting(true)
        try {
            const amount = community.price || 50.00
            const itemName = `${community.name} Subscription`

            const result = await initiateCommunityPayment(
                id,
                user.id,
                amount,
                itemName
            )

            if (!result.success) {
                throw new Error(result.error)
            }

            const form = document.createElement('form')
            form.method = 'POST'
            form.action = result.payfastUrl
            
            Object.entries(result.payfastData).forEach(([key, value]) => {
                const input = document.createElement('input')
                input.type = 'hidden'
                input.name = key
                input.value = value
                form.appendChild(input)
            })
            
            document.body.appendChild(form)
            form.submit()

        } catch (error) {
            console.error('Payment error:', error)
            showToast('Failed to process payment: ' + error.message, 'error')
        } finally {
            setSubmitting(false)
        }
    }

    // ✅ Handle Image Selection
    const handleImageUpload = (e) => {
        const file = e.target.files[0]
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                showToast('Image too large. Max 5MB.', 'error')
                return
            }
            setSelectedImage(file)
            const reader = new FileReader()
            reader.onload = () => {
                setImagePreview(reader.result)
            }
            reader.readAsDataURL(file)
        }
    }

    const removeImage = () => {
        setSelectedImage(null)
        setImagePreview(null)
        if (fileInputRef.current) {
            fileInputRef.current.value = ''
        }
    }

    const handleCreatePost = async (e) => {
        e.preventDefault()
        if (!newPost.trim() && !selectedImage) {
            showToast('Please write something or add an image', 'warning')
            return
        }

        if (!isCreator) {
            showToast('Only the community creator can post in this community.', 'error')
            return
        }

        setSubmitting(true)
        try {
            let imageUrl = null
            
            // ✅ Upload image if selected
            if (selectedImage) {
                try {
                    imageUrl = await uploadImage(selectedImage, user.id, 'post-images')
                } catch (error) {
                    showToast('Failed to upload image: ' + error.message, 'error')
                    setSubmitting(false)
                    return
                }
            }

            const postData = {
                community_id: id,
                user_id: user.id,
                text: newPost.trim(),
                image: imageUrl // ✅ Save image URL
            }

            if (predictionData.result) {
                postData.prediction_data = predictionData
            }

            const { data, error } = await supabase
                .from('community_posts')
                .insert(postData)
                .select()
                .single()

            if (error) throw error

            const { data: communityData } = await supabase
                .from('communities')
                .select('post_count')
                .eq('id', id)
                .single()

            await supabase
                .from('communities')
                .update({ post_count: (communityData?.post_count || 0) + 1 })
                .eq('id', id)

            setNewPost('')
            removeImage()
            setPredictionData({
                result: 'Draw',
                yellowCards: 2,
                redCards: 0,
                corners: 5,
                offsides: 1
            })
            await loadCommunityData()
            showToast('Post created successfully!', 'success')
        } catch (error) {
            console.error('Error creating post:', error)
            showToast('Failed to create post: ' + error.message, 'error')
        } finally {
            setSubmitting(false)
        }
    }

    const handleLike = async (postId) => {
        if (!user) {
            showToast('Please sign in to like posts', 'warning')
            return
        }

        try {
            const { data: existing } = await supabase
                .from('community_post_likes')
                .select('*')
                .eq('post_id', postId)
                .eq('user_id', user.id)
                .maybeSingle()

            const { data: postData } = await supabase
                .from('community_posts')
                .select('likes_count')
                .eq('id', postId)
                .single()

            const currentLikes = postData?.likes_count || 0

            if (existing) {
                await supabase
                    .from('community_post_likes')
                    .delete()
                    .eq('post_id', postId)
                    .eq('user_id', user.id)

                await supabase
                    .from('community_posts')
                    .update({ likes_count: Math.max(0, currentLikes - 1) })
                    .eq('id', postId)
            } else {
                await supabase
                    .from('community_post_likes')
                    .insert({ post_id: postId, user_id: user.id })

                await supabase
                    .from('community_posts')
                    .update({ likes_count: currentLikes + 1 })
                    .eq('id', postId)
            }

            loadCommunityData()
        } catch (error) {
            console.error('Error liking post:', error)
            showToast('Failed to like post. Please try again.', 'error')
        }
    }

    if (loading) {
        return <div className="text-center py-12"><div className="text-gray-500">Loading...</div></div>
    }

    if (!community) {
        return (
            <div className="text-center py-12 bg-white rounded-xl shadow-md">
                <Building2 className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500">Community not found</p>
                <Link to="/community" className="text-green-600 hover:underline mt-4 block">
                    Back to Communities
                </Link>
            </div>
        )
    }

    return (
        <div>
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                <div className="flex items-start justify-between">
                    <div>
                        <div className="flex items-center gap-2">
                            <Building2 className="w-6 h-6 text-green-600" />
                            <h1 className="text-2xl font-bold text-gray-800">{community.name}</h1>
                            {isCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full">Admin</span>}
                            {isMember && !isCreator && <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded-full">Member</span>}
                        </div>
                        <p className="text-gray-500 mt-1">{community.description || 'A private community for football predictions'}</p>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-400">
                            <span className="flex items-center gap-1"><Users size={14} /> {community.member_count || 0} members</span>
                            <span className="flex items-center gap-1"><FileText size={14} /> {community.post_count || 0} posts</span>
                            <span className="flex items-center gap-1"><DollarSign size={14} /> R{community.price || 50} {community.payment_type === 'monthly' ? '/month' : 'once'}</span>
                        </div>
                        {isCreator && (
                            <div className="mt-2 text-sm text-green-600">
                                <DollarSign size={14} className="inline mr-1" /> You earn 50% per {community.payment_type === 'monthly' ? 'month' : 'payment'} (R{((community.price || 50) * 0.5).toFixed(2)})
                            </div>
                        )}
                    </div>
                    <div>
                        {isCreator ? (
                            <span className="text-sm bg-yellow-100 text-yellow-800 px-4 py-2 rounded-lg">Creator</span>
                        ) : isMember ? (
                            <span className="text-sm bg-green-100 text-green-800 px-4 py-2 rounded-lg">Member</span>
                        ) : (
                            <button onClick={handleJoin} className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition font-medium">
                                Join {community.payment_type === 'monthly' ? 'R' + (community.price || 50) + '/month' : 'R' + (community.price || 50) + ' once'}
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {/* ✅ POST SECTION - Only visible to creator (with Image Upload) */}
            {isCreator && (
                <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                    <div className="flex items-center gap-3 mb-3">
                        <div className="w-8 h-8 bg-green-500 rounded-full flex items-center justify-center text-white text-xs font-bold">
                            {profile?.username?.[0]?.toUpperCase() || 'U'}
                        </div>
                        <span className="text-sm text-gray-600 font-medium">Admin • Posting in {community.name}</span>
                    </div>

                    <form onSubmit={handleCreatePost} className="flex flex-col gap-3">
                        <textarea
                            value={newPost}
                            onChange={(e) => setNewPost(e.target.value)}
                            placeholder="Share your community announcement..."
                            className="w-full px-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500 resize-none bg-white text-gray-800"
                            rows="3"
                        />

                        {/* ✅ Image Preview */}
                        {imagePreview && (
                            <div className="relative mt-2">
                                <img 
                                    src={imagePreview} 
                                    alt="Preview" 
                                    className="max-h-64 rounded-lg object-contain bg-gray-50 w-full"
                                />
                                <button
                                    type="button"
                                    onClick={removeImage}
                                    className="absolute top-2 right-2 bg-gray-800 text-white rounded-full w-8 h-8 flex items-center justify-center hover:bg-gray-700"
                                >
                                    <X size={18} />
                                </button>
                            </div>
                        )}

                        <div className="flex justify-between items-center">
                            <div className="flex gap-2">
                                {/* ✅ Image Upload Button */}
                                <button
                                    type="button"
                                    onClick={() => fileInputRef.current?.click()}
                                    className="text-sm bg-gray-100 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-200 transition flex items-center gap-2"
                                >
                                    <ImageIcon size={16} /> Add Image
                                </button>
                                <input
                                    ref={fileInputRef}
                                    type="file"
                                    accept="image/*"
                                    onChange={handleImageUpload}
                                    className="hidden"
                                />

                                {/* Prediction Button */}
                                <button 
                                    type="button" 
                                    onClick={() => setShowPredictionModal(true)} 
                                    className="text-sm bg-gray-100 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-200 transition flex items-center gap-2"
                                >
                                    <FileText size={16} /> Add Prediction
                                </button>
                            </div>

                            <button 
                                type="submit" 
                                disabled={submitting || (!newPost.trim() && !selectedImage)} 
                                className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 font-medium"
                            >
                                {submitting ? 'Posting...' : 'Post'}
                            </button>
                        </div>
                    </form>
                    <p className="text-xs text-gray-400 mt-3"><Crown size={12} className="inline mr-1" /> Only you can post in this community.</p>
                </div>
            )}

            {/* FEED OF POSTS - Now includes images */}
            {posts.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <FileText className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <p className="text-gray-500">No posts yet</p>
                    <p className="text-sm text-gray-400">The admin hasn't posted anything yet.</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {posts.map((post) => {
                        const isPostCreator = post.user_id === community.creator_id
                        return (
                            <div key={post.id} className={`bg-white rounded-xl shadow-md p-4 ${isPostCreator ? 'border-2 border-yellow-400' : ''}`}>
                                <div className="flex items-center gap-3 mb-3">
                                    <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                                        {post.profiles?.username?.[0]?.toUpperCase() || 'U'}
                                    </div>
                                    <div>
                                        <div className="font-semibold flex items-center gap-1.5">
                                            {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                            {post.profiles?.is_verified && <VerifiedBadge size="sm" />}
                                            {isPostCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded-full"><Crown size={12} className="inline mr-1" /> Admin</span>}
                                        </div>
                                        <div className="text-xs text-gray-400">@{post.profiles?.username} • {new Date(post.created_at).toLocaleDateString()}</div>
                                    </div>
                                </div>
                                <p className="text-gray-800 mb-3">{post.text}</p>

                                {/* ✅ Display Image if exists */}
                                {post.image && (
                                    <img 
                                        src={post.image} 
                                        alt="Post image" 
                                        className="mt-3 rounded-lg max-h-96 w-full object-contain bg-gray-100" 
                                        loading="lazy" 
                                    />
                                )}

                                {post.prediction_data && (
                                    <div className="bg-gray-50 rounded-lg p-3 mb-3 border border-gray-100">
                                        <div className="flex items-center justify-between text-sm">
                                            <span>Prediction: {post.prediction_data.result || 'Draw'}</span>
                                            <span className="text-gray-500">🟨{post.prediction_data.yellowCards || 0} 🟥{post.prediction_data.redCards || 0}</span>
                                        </div>
                                    </div>
                                )}
                                <button 
                                    onClick={() => handleLike(post.id)} 
                                    className="flex items-center gap-1 text-sm text-gray-400 hover:text-red-500 transition"
                                >
                                    <Heart size={16} /> {post.likes_count || 0}
                                </button>
                            </div>
                        )
                    })}
                </div>
            )}

            {/* Payment Modal */}
            {showPaymentModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                                <DollarSign size={20} /> Join {community.name}
                            </h2>
                            <button 
                                onClick={() => setShowPaymentModal(false)}
                                className="text-gray-400 hover:text-gray-600"
                            >
                                <X size={24} />
                            </button>
                        </div>
                        
                        <div className="bg-gray-50 rounded-lg p-4 mb-4">
                            <div className="flex justify-between items-center">
                                <span className="text-gray-600">
                                    {community.payment_type === 'monthly' ? 'Monthly subscription' : 'One-time payment'}
                                </span>
                                <span className="font-bold text-xl">R{community.price || 50}</span>
                            </div>
                        </div>

                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowPaymentModal(false)}
                                className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handlePayment}
                                disabled={submitting}
                                className="flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {submitting ? (
                                    <>
                                        <Loader size={18} className="animate-spin" /> Processing...
                                    </>
                                ) : (
                                    <>
                                        <DollarSign size={18} /> Pay R{community.price || 50}
                                    </>
                                )}
                            </button>
                        </div>

                        <p className="text-xs text-gray-400 text-center mt-4">
                            You will be redirected to PayFast to complete payment securely.
                        </p>
                    </div>
                </div>
            )}

            {/* Prediction Modal */}
            {showPredictionModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6 max-h-[90vh] overflow-y-auto">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold text-gray-800">Add Prediction</h3>
                            <button onClick={() => setShowPredictionModal(false)} className="text-gray-400 hover:text-gray-600">
                                <X size={24} />
                            </button>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">Result</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {['Home Win', 'Draw', 'Away Win'].map((result) => (
                                        <button 
                                            key={result} 
                                            onClick={() => setPredictionData({...predictionData, result})} 
                                            className={`px-3 py-2 rounded-lg text-sm font-medium transition ${predictionData.result === result ? 'bg-green-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
                                        >
                                            {result === 'Home Win' ? 'Home' : result === 'Away Win' ? 'Away' : 'Draw'}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Yellow Cards</label>
                                    <input type="number" min="0" max="10" value={predictionData.yellowCards} onChange={(e) => setPredictionData({...predictionData, yellowCards: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Red Cards</label>
                                    <input type="number" min="0" max="5" value={predictionData.redCards} onChange={(e) => setPredictionData({...predictionData, redCards: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" />
                                </div>
                            </div>
                            <button 
                                onClick={() => { setShowPredictionModal(false); showToast('Prediction added! Submit the post to share it.', 'success'); }} 
                                className="w-full bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition"
                            >
                                Add to Post
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
